    if (/^[a-z][a-z\d+.-]*:/i.test(path)) {
        return path;
    }
    const url = new URL(path.replace(/^\/+/, ''), `${window.location.origin}${resolveAppBase()}`);
    return `${url.pathname}${url.search}${url.hash}`;
}

